This FIFO holds exactly 17 integers and rejects overflow without modifying its contents. The invariant is 0 ≤ size ≤ 17, with tail = (head + size) modulo 17; when head equals tail, size distinguishes empty (0) from full (17). Compile and run with `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo && ./fifo`; the tests require assertions enabled.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

#ifdef NDEBUG
#error "Compile this test with assertions enabled (without -DNDEBUG)."
#endif

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) {
            return false;
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++size_;
        return true;
    }

    bool pop(int& value) {
        if (size_ == 0) {
            return false;
        }
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -1;

    assert(queue.empty());
    assert(!queue.pop(value));
    assert(value == -1);

    // All 17 slots are usable.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
        assert(queue.size() == static_cast<std::size_t>(i + 1));
    }
    assert(queue.full());

    // Rejection preserves both size and contents.
    assert(!queue.push(999));
    assert(queue.size() == 17);
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    // Keep live elements while wrapping the insertion index.
    for (int i = 0; i < 12; ++i) {
        assert(queue.push(i));
    }
    for (int i = 0; i < 7; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    for (int i = 12; i < 24; ++i) {
        assert(queue.push(i));
    }
    assert(queue.full());
    assert(!queue.push(999));

    // Draining also wraps the removal index.
    for (int i = 7; i < 24; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(queue.size() == 0);
    assert(!queue.pop(value));

    std::cout << "All tests passed\n";
}
```

Copy the input, then use `std::nth_element` at index `(n - 1) / 2`; the caller’s array stays unchanged, and empty input throws `std::invalid_argument`. For odd size `n = 2m + 1`, that index is `m`, the middle element; for even size `n = 2m`, it is `m - 1`, the lower of the two middle elements. `nth_element` places the value that would occupy that index in sorted order, including duplicates, so the lower median of `[9,1,4,4,7,2]` is 4.

Compile and run with `g++ -std=c++17 -Wall -Wextra -pedantic median.cpp -o median && ./median`; assertions must be enabled.

```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

#ifdef NDEBUG
#error "Compile tests without -DNDEBUG."
#endif

int lower_median(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("lower_median requires nonempty input");
    }

    std::vector<int> copy = input;
    const std::size_t index = (copy.size() - 1) / 2;
    const auto middle = copy.begin() +
        static_cast<std::vector<int>::difference_type>(index);
    std::nth_element(copy.begin(), middle, copy.end());
    return *middle;
}

void check(const std::vector<int>& input, int expected) {
    const std::vector<int> original = input;
    assert(lower_median(input) == expected);
    assert(input == original);
}

int main() {
    check({9, 1, 4, 4, 7, 2}, 4); // Duplicates: sorted 1,2,4,4,7,9.
    check({5, 1, 3, 2, 4}, 3);    // Odd size.
    check({8, 2, 6, 4}, 4);       // Even size: lower middle, not 6.
    check({42}, 42);              // Singleton.
    check({4, 4, 4, 4}, 4);       // All values equal.

    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lower_median(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());

    std::cout << "All tests passed\n";
}
```

No: retrying with a stale `desired` can lose an increment. Two threads both start with `expected = 0`, `desired = 1`: T1 successfully changes 0 to 1; T2 fails, updating its `expected` to 1, then successfully changes 1 to its stale `desired = 1`. Both finish, but the count is only 1 instead of 2.

Recompute `desired` on every attempt. A spurious failure performs no update, so the loop simply recomputes and retries; relaxed ordering suffices for this standalone counter, not for publishing unrelated data. Compile with `g++ -std=c++17 -pthread -Wall -Wextra -pedantic counter.cpp -o counter` and run with assertions enabled.

```cpp
#include <atomic>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

#ifdef NDEBUG
#error "Compile this test without -DNDEBUG."
#endif

void increment(std::atomic<std::uint64_t>& counter) {
    std::uint64_t expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        const std::uint64_t desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // Failure updates expected with the observed value.
        // Recompute desired even if the failure was spurious.
    }
}

int main() {
    constexpr unsigned thread_count = 4;
    constexpr std::uint64_t increments_per_thread = 25000;
    constexpr std::uint64_t expected_count =
        thread_count * increments_per_thread;

    // This test stays well below uint64_t's overflow boundary.
    std::atomic<std::uint64_t> counter{0};
    std::vector<std::thread> workers;
    workers.reserve(thread_count);

    for (unsigned t = 0; t < thread_count; ++t) {
        workers.emplace_back([&counter] {
            for (std::uint64_t i = 0; i < increments_per_thread; ++i) {
                increment(counter);
            }
        });
    }
    for (auto& worker : workers) {
        worker.join();
    }

    const std::uint64_t actual = counter.load(std::memory_order_relaxed);
    assert(actual == expected_count);
    std::cout << "All tests passed; final count = " << actual << '\n';
}
